        abrirModal: function abrirModal(modelo, accion, data) {
            switch (modelo) {
                case "articulo":
                    {
                        switch (accion) {
                            case 'registrar':
                                {
                                    this.modal = 1;
                                    this.tituloModal = 'Registrar Artículo';
                                    this.tipoAccion = 1;
                                    this.articulo = {
                                        'id': 0,
                                        'codigo': 1,
                                        'idcategoria': 1,
                                        'categorias_ids': [1],
                                        'id_item_padre': 0,
                                        'tipo_producto_id': 1,
                                        'nombre': '',
                                        'stock': 0,
                                        'tamano': '',
                                        'medida_final': '',
                                        'ancho_final': 0,
                                        'largo_final': 0,
                                        'precio_venta': 0,
                                        'descripcion': '',
                                        'etiquetas': '',
                                        'ancho': 0,
                                        'largo': 0,
                                        'alto': 0,
                                        'volumen': 0,
                                        'imagenes': [],
                                        'cabidas_materiales': []
                                    };
                                    break;
                                }
                            case 'actualizar':
                                {
                                    this.modal = 1;
                                    this.tituloModal = 'Actualizar Artículo';
                                    this.tipoAccion = 2;
                                    this.articulo = data;
                                    var catIds = [];
                                    if (data['categorias'] && data['categorias'].length > 0) {
                                        catIds = data['categorias'].map(function (c) {
                                            return c.id;
                                        });
                                    } else if (data['idcategoria']) {
                                        catIds = [data['idcategoria']];
                                    }
                                    this.$set(this.articulo, 'categorias_ids', catIds);
                                    var cabidas = data['cabidas_materiales'];
                                    if (typeof cabidas === 'string') {
                                        try {
                                            cabidas = JSON.parse(cabidas);
                                        } catch (e) {
                                            cabidas = [];
                                        }
                                    }
                                    this.$set(this.articulo, 'cabidas_materiales', cabidas || []);
                                    this.articulo_id = data['id'];
                                    this.idcategoria = data['idcategoria'];
                                    this.idarticulo_padre = data['id_item_padre'];
                                    this.codigo = data['codigo'];
                                    this.nombre = data['nombre'];
                                    this.stock = data['stock'];
                                    this.precio_venta = data['precio_venta'];
                                    this.iva = data['iva'];
                                    this.descripcion = data['descripcion'];
                                    this.tamano = data['tamano'];
                                    if (data['rangos'] == null) {
                                        this.rangos = [];
                                    } else {
                                        this.rangos = data['rangos'];
                                    }
                                    if (data['cantidades'] == 0) {
                                        this.cantidades = { 'tipo_cantidad': 1, 'valores': [1, 1000] };
                                    } else {
                                        this.cantidades = data['cantidades'];
                                    }
                                    if (data['imagen'].length == 0) {
                                        this.imagen = [];
                                    } else {
                                        this.imagen = data['imagen'];
                                    }
                                    this.imagenMin = [];

                                    break;
                                }
                        }
                    }
            }
            this.selectCategoria();
        },


