    getEntregaColor: function getEntregaColor(fechaEntrega) {
      var hoy = new Date();
      var entrega = new Date(fechaEntrega);

      // Normalizar horas
      hoy.setHours(0, 0, 0, 0);
      entrega.setHours(0, 0, 0, 0);

      var diffMs = entrega - hoy;
      var diasRestantes = Math.ceil(diffMs / (1000 * 60 * 60 * 24));

      var diasMax = 12; // cantidad de días desde verde hasta rojo

      // Progreso de 0 (fecha vencida o hoy) a 1 (muy anticipado)
      var progreso = Math.max(0, Math.min(1, diasRestantes / diasMax));
      // Hue va de 0 (rojo) a 120 (verde), así que lo invertimos
      var hue = Math.round(170 * progreso); // 120 = verde, 0 = rojo

      if (hue > 120) {
        var d = hue - 120;
        hue = 120 - d / 2;
      }

      var color = 'hsl(' + hue + ', 100%, 50%)';

      return color;
    },
