        obtenerCreditoProveedor: function obtenerCreditoProveedor() {
            var me = this;
            var provId = me.cuentaForm.proveedor_id;
            if (!provId) {
                me.cupo_credito = 0;
                me.saldo_pendiente = 0;
                me.cupo_disponible = 0;
                return;
            }
            axios.get('/proveedor/obtenerEstadoCredito?id=' + provId).then(function (response) {
                var data = response.data;
                me.cupo_credito = parseFloat(data.cupo_credito);
                me.saldo_pendiente = parseFloat(data.saldo_pendiente);
                me.cupo_disponible = parseFloat(data.cupo_disponible);
            }).catch(function (error) {
                console.error(error);
            });
        },
        obtenerClaseVencimiento: function obtenerClaseVencimiento(fechaVencimiento) {
            if (!fechaVencimiento) return '';
            var hoy = new Date();
            hoy.setHours(0, 0, 0, 0);
            var venc = new Date(fechaVencimiento + 'T00:00:00');
            var diffTime = venc - hoy;
            var diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

            if (diffDays < 0) {
                return 'vencido';
            } else if (diffDays === 0) {
                return 'vence-hoy';
            } else if (diffDays <= 5) {
                return 'vence-pronto';
            } else {
                return 'vence-ok';
            }
        },
        obtenerTextoVencimiento: function obtenerTextoVencimiento(fechaVencimiento) {
            if (!fechaVencimiento) return '';
            var hoy = new Date();
            hoy.setHours(0, 0, 0, 0);
            var venc = new Date(fechaVencimiento + 'T00:00:00');
            var diffTime = venc - hoy;
            var diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

            if (diffDays < 0) {
                var absDays = Math.abs(diffDays);
                return 'Vencido hace ' + absDays + ' ' + (absDays === 1 ? 'día' : 'días');
            } else if (diffDays === 0) {
                return 'Vence hoy';
            } else if (diffDays === 1) {
                return 'Vence mañana';
            } else {
                return 'Vence en ' + diffDays + ' d\xEDas';
            }
        },
