            var fVenc = new Date(fecha + 'T00:00:00');
            var diffDays = Math.ceil((fVenc - today) / (1000 * 60 * 60 * 24));

            if (diffDays < 0) return '¡VENCIDO! (' + Math.abs(diffDays) + ' días)';
            if (diffDays === 0) return '¡VENCE HOY!';
            if (diffDays === 1) return 'Vence mañana';
